INSERT INTO repository_markdown_sources(
    id,repo_id,branch_id,content_version,file_path,content_hash,title,asset_type,content,line_count,byte_size
) VALUES(
    #{id},#{repositoryId},#{branchId},#{contentVersion},#{filePath},#{contentHash},#{title},#{assetType},
    #{content},#{lineCount},#{byteSize}
)
ON CONFLICT(repo_id,branch_id,file_path) DO UPDATE SET
    content_version=EXCLUDED.content_version,content_hash=EXCLUDED.content_hash,title=EXCLUDED.title,
    asset_type=EXCLUDED.asset_type,content=EXCLUDED.content,line_count=EXCLUDED.line_count,
    byte_size=EXCLUDED.byte_size,updated_at=CURRENT_TIMESTAMP

