mapper.select:
SELECT ,s.content
FROM repository_markdown_sources s

WHERE s.repo_id=#{repositoryId} AND s.content_version=#{contentVersion} AND s.file_path=#{filePath}

SELECT id FROM code_chunks
WHERE repo_id=#{repositoryId} AND content_version=#{contentVersion} AND file_path=#{filePath}
ORDER BY start_line NULLS FIRST,id
LIMIT #{limit}

mapper.insert:
INSERT INTO knowledge_card_markdown_source_links(
    card_id,revision,source_id,repo_id,source_branch_id,source_content_version,source_path,source_content_hash
)
SELECT #{cardId},#{revision},#{sourceId},#{repositoryId},s.branch_id,#{sourceContentVersion},
       #{sourcePath},#{sourceContentHash}
FROM repository_markdown_sources s
WHERE s.id=#{sourceId} AND s.repo_id=#{repositoryId}
